// Some portions generated by Codex

const { test, expect } = require('@playwright/test');
const { createServer } = require('./workbench-preview-scroll-fixture.cjs');

let fixture;
let baseUrl;

test.beforeAll(async () => {
    fixture = createServer();
    await new Promise((resolve, reject) => {
        fixture.once('error', reject);
        fixture.listen(0, '127.0.0.1', resolve);
    });
    const address = fixture.address();
    if (!address || typeof address === 'string') {
        throw new Error('The Workbench fixture did not bind a TCP port.');
    }
    baseUrl = `http://127.0.0.1:${address.port}`;
});

test.afterAll(async () => {
    if (fixture && fixture.listening) {
        await new Promise((resolve, reject) => fixture.close(error => error ? reject(error) : resolve()));
    }
});

test('repository list sorts complete rows and keeps icon and action columns fixed', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/repositories`, { waitUntil: 'networkidle' });

    const card = page.locator('#repositories-results');
    const table = card.locator('table.data');
    await expect(table.locator('tbody tr[data-workbench-row-index]')).toHaveCount(4);
    const create = card.getByRole('link', { name: 'Create repository' });
    expect.soft(await create.count(), 'the prominent create action names its destination').toBe(1);
    if (await create.count()) {
        await expect.soft(create).toHaveAttribute('href', /\/repositories\/NONE\/create$/);
        const createHeight = await create.evaluate(element => element.getBoundingClientRect().height);
        expect.soft(createHeight, 'the create repository action has a larger touch target').toBeGreaterThanOrEqual(44);
    }

    const headers = table.locator('thead th');
    expect.soft(await headers.evaluateAll(elements => elements.map(element => {
        const label = element.querySelector('button span');
        return (label || element).textContent.trim();
    }))).toEqual(['Repository', 'ID', 'Title', 'Access', 'Actions']);
    const sortButtons = table.locator('thead button[data-workbench-sort]');
    expect.soft(await sortButtons.count(), 'only ID, Title, and Access have sort controls').toBe(3);

    const fixedHeaders = await Promise.all(['repository', 'actions'].map(async column => {
        const header = table.locator(`thead th[data-repository-column="${column}"]`);
        if (!await header.count()) {
            return { column, buttons: 0, sort: null };
        }
        return header.evaluate(element => ({
            column: element.getAttribute('data-repository-column'),
            buttons: element.querySelectorAll('button').length,
            sort: element.getAttribute('aria-sort')
        }));
    }));
    expect.soft(fixedHeaders).toEqual([
        { column: 'repository', buttons: 0, sort: null },
        { column: 'actions', buttons: 0, sort: null }
    ]);
    const repositoryHeader = table.locator('thead th[data-repository-column="repository"]');
    const iconHeaderWidth = await repositoryHeader.evaluate(element => element.getBoundingClientRect().width);
    expect.soft(iconHeaderWidth, 'the decorative icon column stays compact').toBeLessThan(80);
    const repositoryHeaderLabel = repositoryHeader.locator('.workbench-visually-hidden');
    expect.soft(await repositoryHeaderLabel.count(), 'the compact header keeps an accessible name').toBe(1);
    if (await repositoryHeaderLabel.count()) {
        expect.soft(await repositoryHeaderLabel.textContent()).toBe('Repository');
    }

    const rowSnapshot = async () => table.locator('tbody tr[data-workbench-row-index]').evaluateAll(rows => rows.map(row => {
        const title = row.querySelector('td[data-label="Title"]');
        const access = row.querySelector('td[data-label="Access"]');
        const action = row.querySelector('td[data-label="Actions"] button');
        const repository = row.querySelector('td[data-label="Repository"]');
        return {
            id: row.querySelector('.workbench-repository-link')?.textContent.trim() || '',
            title: title?.textContent.trim() || '',
            access: access?.innerText.trim().replace(/\s+/g, ' ') || '',
            action: action?.getAttribute('aria-label') || '',
            repositoryIcons: repository?.querySelectorAll('svg[data-workbench-icon="repository"]').length || 0,
            accessIcons: Array.from(access?.querySelectorAll('.workbench-badge svg[data-workbench-icon]') || [])
                .map(icon => icon.getAttribute('data-workbench-icon')).sort()
        };
    }));

    const initialRows = await rowSnapshot();
    expect.soft(initialRows.map(row => row.id)).toEqual(['repo-1', 'repo-2', 'repo-3', 'repo-10']);
    expect.soft(initialRows.map(row => row.title)).toEqual(['', 'Alpha store', 'alpha store', 'Zulu store']);
    expect.soft(initialRows.map(row => row.access)).toEqual(['None', 'Read Write', 'Write', 'Read']);
    expect.soft(initialRows.every(row => row.repositoryIcons === 1), 'each repository row has one repository icon').toBe(true);
    expect.soft(initialRows.map(row => row.accessIcons)).toEqual([[], ['edit', 'eye'], ['edit'], ['eye']]);
    expect.soft(initialRows.map(row => row.action)).toEqual([
        'Actions for repo-1', 'Actions for repo-2', 'Actions for repo-3', 'Actions for repo-10'
    ]);
    await page.screenshot({ path: '../.agent/evidence/workbench-repository-list-features/repository-list-desktop.png', fullPage: true });

    if (await sortButtons.count() === 3) {
        const idHeader = table.locator('thead th[data-repository-column="id"]');
        const idSort = table.locator('button[data-workbench-sort="id"]');
        await idSort.focus();
        await page.keyboard.press('Enter');
        await expect(idHeader).toHaveAttribute('aria-sort', 'ascending');
        expect((await rowSnapshot()).map(row => row.id)).toEqual(['repo-1', 'repo-2', 'repo-3', 'repo-10']);
        await table.locator('button[data-workbench-sort="id"]').click();
        await expect(idHeader).toHaveAttribute('aria-sort', 'descending');
        const descendingSortPseudo = await idHeader.evaluate(element => getComputedStyle(element, '::after').content);
        expect.soft(descendingSortPseudo, 'the direction indicator is not duplicated by the shared browse-table rule')
            .toBe('none');
        expect(await rowSnapshot()).toEqual([
            { id: 'repo-10', title: 'Zulu store', access: 'Read', action: 'Actions for repo-10', repositoryIcons: 1, accessIcons: ['eye'] },
            { id: 'repo-3', title: 'alpha store', access: 'Write', action: 'Actions for repo-3', repositoryIcons: 1, accessIcons: ['edit'] },
            { id: 'repo-2', title: 'Alpha store', access: 'Read Write', action: 'Actions for repo-2', repositoryIcons: 1, accessIcons: ['edit', 'eye'] },
            { id: 'repo-1', title: '', access: 'None', action: 'Actions for repo-1', repositoryIcons: 1, accessIcons: [] }
        ]);

        const titleHeader = table.locator('thead th[data-repository-column="title"]');
        await table.locator('button[data-workbench-sort="title"]').click();
        await expect(titleHeader).toHaveAttribute('aria-sort', 'ascending');
        expect((await rowSnapshot()).map(row => row.id)).toEqual(['repo-1', 'repo-2', 'repo-3', 'repo-10']);
        await table.locator('button[data-workbench-sort="title"]').click();
        await expect(titleHeader).toHaveAttribute('aria-sort', 'descending');
        expect((await rowSnapshot()).map(row => row.id)).toEqual(['repo-10', 'repo-2', 'repo-3', 'repo-1']);

        const accessHeader = table.locator('thead th[data-repository-column="access"]');
        await table.locator('button[data-workbench-sort="access"]').click();
        await expect(accessHeader).toHaveAttribute('aria-sort', 'ascending');
        expect((await rowSnapshot()).map(row => row.id)).toEqual(['repo-1', 'repo-10', 'repo-2', 'repo-3']);

        await page.setViewportSize({ width: 390, height: 844 });
        for (const column of ['id', 'title', 'access']) {
            await expect(table.locator(`button[data-workbench-sort="${column}"]`)).toBeVisible();
        }
        const viewportWidths = await page.evaluate(() => ({
            viewport: document.documentElement.clientWidth,
            body: document.body.scrollWidth
        }));
        expect(viewportWidths.body, 'repository list does not force horizontal page scrolling').toBeLessThanOrEqual(viewportWidths.viewport);
        const repositoryCardWidths = await table.locator('tbody tr[data-workbench-row-index]').evaluateAll(rows =>
            rows.map(row => row.getBoundingClientRect().width));
        expect(repositoryCardWidths.every(width => width >= 280),
            `repository cards remain readable at narrow width; actual widths: ${repositoryCardWidths.join(', ')}`).toBe(true);
        const narrowTitleSort = table.locator('button[data-workbench-sort="title"]');
        await narrowTitleSort.focus();
        await page.keyboard.press('Enter');
        await expect(titleHeader).toHaveAttribute('aria-sort', 'ascending');
        expect((await rowSnapshot()).map(row => row.id)).toEqual(['repo-1', 'repo-2', 'repo-3', 'repo-10']);
    }
});
